           "**/*.test.cts",
           "**/*.spec.ts",
           "**/*.spec.tsx",
           "**/*.spec.mts",
           "**/*.spec.cts",
           "**/tests/**",
           "**/generated/**",
           "**/dist/**",
           "**/*.d.ts",
         ],
         rules: { "tsdoc/syntax": "error", "tsdoc-require-2/require": "error" },
       },
       {
         // `scripts/` trees are invoked as `node script.ts`, and Node's strip-only type removal
         // can't rewrite a TS parameter property into a field assignment — it's a runtime
         // SyntaxError that both typecheck and the (transpiling) test runner miss, so it only
         // surfaces in CI. Package sources and tests are bundled or transpiled, where the syntax is
         // fine, so the ban is scoped to the files Node parses directly.
         files: ["**/scripts/**/*.ts", "**/scripts/**/*.mts"],
         rules: { "typescript/parameter-properties": "error" },
       },
     ],
   },
   run: {
     cache: true,
     tasks: {
       // `ready:all` is a task DAG, not a serial `&&` chain: `build:all` runs once, then the independent
       // gates fan out concurrently. `command: "true"` makes it a pure aggregator whose only job is to
       // pull its `dependsOn` (the root `ready` script is `vp run ready:all` — a task and a package.json
       // script may not share a name). Everything that needs generated output funnels through `build:all`,
       // the single generation path, so no two nodes run the component codegen at once (a `vp run -r build`
       // and a bare `@pantoken/components#generate` writing the same `generated/` dir would race).
       "build:all": {
         command: "vp run -r build",
       },
       "check:all": {
         command: "node docs/scripts/site-themes.ts && vp check",
         dependsOn: ["build:all"],
       },
       "test:all": {
         command: "vp run -r test",
         dependsOn: ["build:all"],
       },
       // Coverage run for Codecov + fallow health; needs generated output like the plain test run.

