/**
 * @component button
 * @summary An accessible action control, styled from the token palette; primary by default.
 * @remarks The AI variants layer two gradients — a padding-box fill and a border-box stroke — for their frame, and `-color-ai-secondary` can't paint gradient text and a fill at once, so its centre stays transparent at rest and fills on hover or active. `-without-background` reads the resolved ghost-state tokens. Buttons with an icon and no visible label become square automatically. Also sets its own icon/label `gap` and horizontal `padding`; chaining a `-gap-*`/`-p-*`/`-padding-*` spacing utility modifier overrides those built-in values. The optional `.pfx-button-group` wrapper maps Figma's `.buttonGroup` and owns adjacent button spacing.
 * @selector .pfx-button
 * @modifier -color-primary — (default) the primary action.
 * @modifier -color-secondary — A lower-emphasis secondary action.
 * @modifier -color-tertiary — A text-style action (no fill or border until hover).
 * @modifier -color-danger — A destructive action.
 * @modifier -shape-circle — A round icon button.
 * @modifier -condensed — Tighter padding for dense toolbars.
 * @modifier -toggle — A pressed-state toggle button (drive with aria-pressed).
 * @modifier -without-background — Drop the fill (ghost).
 * @modifier -color-success — A positive/confirming action.
 * @modifier -color-ai — An AI action.
 * @modifier -color-ai-secondary — A lower-emphasis AI action.
 * @modifier -color-primary-inverse — @deprecated {@link -on-color}
 * @modifier -on-color — For a button placed on a coloured (non-neutral) surface. Composed with `-color-primary` (default) fills white with dark text; composed with `-color-secondary` stays transparent with a white border and text.
 * @modifier -size-sm — Small.
 * @modifier -size-md — (default) medium size.
 * @modifier -size-lg — Large.
 * @modifier -shape-square — A square icon button.
 * @modifier -display-block — Full-width block button.
 * @modifier -ghost — @deprecated {@link -color-tertiary}
 * @modifier -without-border — Remove the border.
 * @modifier -icon-* — Render a glyph from the icon set before the label (e.g. `-icon-arrow-right`), painted in the button's text colour; pair with `-shape-square`/`-shape-circle` for an icon-only button.
 * @pseudo ::before — The AI glyph, added automatically to AI buttons and masked in the variant's own colour.
 * @pseudo ::after — The AI-secondary gradient border ring, masked to just the button's frame.
 * @cssstate disabled
 * @cssstate pressed
 * @a11y Drive the `-toggle` variant's pressed state with `aria-pressed`, and mark a disabled button with `aria-disabled` (or the native `disabled`).
 * @example -canvas-rce
 * ```html
 * <div class="pfx-button-group">
 *   <button class="pfx-button">Primary</button>
 *   <button class="pfx-button -color-secondary">Secondary</button>
 * </div>
 * ```
 * @example -automatica11y
 * ```html
 * <button class="pfx-button" data-a11y-trigger data-a11y-root>Save</button>
 * ```
 * @example -docs
 * ```html
 * <div class="pfx-button-group">
 *   <button class="pfx-button -color-danger">Delete</button>
 *   <button class="pfx-button -color-secondary">Cancel</button>
 * </div>
 * ```
 * @wrapper pfx-button-group
 * @structure
 * A group wrapper lays out adjacent buttons with the shared button gap.
 * .pfx-button-group:opt {
 *   .pfx-button:one-or-more {}
 * }
 * @related close-button — The icon-only dismiss button.
 * @demo self:button
 */
@scope (.pfx-button) {
  & {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    gap: var(--instui-spacing-space-xs);
    min-height: var(--instui-component-base-button-medium-height);
    padding: var(--instui-spacing-space-xs)
      var(--instui-component-base-button-medium-padding-horizontal);
    font-family: var(--instui-font-family-base);
    font-size: var(--instui-component-base-button-medium-font-size);
    font-weight: var(--instui-font-weight-interactive);
    line-height: var(--instui-line-height-standalone-text-base);
    border: var(--instui-border-width-sm) solid transparent;
    border-radius: var(--instui-component-base-button-border-radius);
    cursor: pointer;
    background: var(--instui-color-background-interactive-action-primary-base);
    color: var(--instui-color-text-interactive-action-primary-base);
    text-decoration: none;
  }

  &:hover {
    background: var(--instui-color-background-interactive-action-primary-hover);
  }

  &:active {
    background: var(--instui-color-background-interactive-action-primary-active);
  }

  /* A bare button is primary, so it takes -color-primary's stroke too. */
  &:not(
    [class*="-color-"],
