    await npm(["install", "svelte", ...pinnedRuntime(dir, ["svelte"]), ...NPM_FLAGS, "--legacy-peer-deps"]);
    warnings.push(`${name} didn't bring in svelte, so the latest svelte was added.`);
  }
  if (flavor === "angular") {
